const l={"p1-droit-t1":[["Droit objectif","Ensemble des règles qui organisent la vie en société."],["Droit subjectif","Prérogative reconnue à une personne (droit de propriété, de vote)."],["Règle de droit","Règle générale, obligatoire et sanctionnée par l’État."],["Source du droit","Origine des règles : Constitution, lois, règlements, jurisprudence."],["Hiérarchie des normes","Classement des règles où chacune respecte celle qui lui est supérieure."],["Jurisprudence","Ensemble des décisions rendues par les tribunaux."]],"p1-droit-t2":[["Litige","Désaccord entre personnes portant sur des droits."],["Juridiction","Tribunal chargé de juger un litige."],["Ordre judiciaire","Tribunaux réglant les litiges entre particuliers et jugeant les infractions."],["Ordre administratif","Tribunaux réglant les litiges impliquant l’administration."],["Preuve","Élément établissant l’existence d’un droit ou d’un fait."],["Voie de recours","Moyen de contester une décision (appel, cassation)."]],"p1-droit-t3":[["Personne juridique","Être titulaire de droits et d’obligations."],["Personne physique","Être humain, sujet de droit dès la naissance."],["Personne morale","Groupement (société, association) doté de la personnalité juridique."],["Capacité juridique","Aptitude à avoir des droits et à les exercer."],["Patrimoine","Ensemble des biens, droits et obligations d’une personne."],["Action en justice","Droit de saisir un tribunal pour faire valoir ses droits."]],"p1-droit-t4":[["Droits patrimoniaux","Droits évaluables en argent (propriété, créances)."],["Droits extrapatrimoniaux","Droits sans valeur marchande (droit au nom, à l’image)."],["Droit de propriété","Droit d’user, de jouir et de disposer d’un bien."],["Droits de la personnalité","Droits protégeant la personne (vie privée, image, honneur)."],["Respect de la vie privée","Droit à la protection de son intimité (art. 9 du Code civil)."],["Propriété intellectuelle","Protection des créations de l’esprit (œuvres, inventions, marques)."]]},g=Object.freeze(Object.defineProperty({__proto__:null,default:l},Symbol.toStringTag,{value:"Module"})),u={"p1-droit-t1":{sections:[{h:"⚖️ Exemple — griller un feu rouge : règle de droit ou règle morale ?",group:"cas",blocks:[{t:"example",h:"Situation",c:"Griller un feu rouge : est-ce une faute morale ou juridique ? Quelle différence ?"},{t:"list",c:["La **règle de droit** est **générale, obligatoire et sanctionnée** par l’État (amende, retrait de points).","La **morale**, elle, n’est pas sanctionnée par l’État (seulement par la conscience).","**Droit objectif** = l’ensemble des règles ; **droits subjectifs** = les prérogatives d’une personne (ex. droit de propriété)."]},{t:"tip",h:"À distinguer",c:"Ce qui caractérise le droit : la **sanction organisée par l’État**. C’est ce qui le sépare de la morale."}]}]},"p1-droit-t2":{sections:[{h:"⚖️ Exemple — un client non livré : parties, preuve, modes de résolution",group:"cas",blocks:[{t:"example",h:"Situation",c:"Un client n’est pas livré malgré son paiement : un litige naît avec le vendeur."},{t:"list",c:["**Les parties** : le demandeur (le client) et le défendeur (le vendeur).","**Modes de résolution** : à l’amiable (négociation, médiation, conciliation) ou en justice (procès).","**La preuve** : « qui allègue un fait doit le prouver » (facture, contrat, mails)."]},{t:"tip",h:"Réflexe",c:"Avant le procès, on privilégie les modes **amiables** (plus rapides et moins coûteux)."}]}]},"p1-droit-t3":{sections:[{h:"⚖️ Exemple — créer une société : personne physique, personne morale, capacité",group:"cas",blocks:[{t:"example",h:"Cas",c:"Une jeune femme de 25 ans crée une entreprise sous forme de société."},{t:"list",c:["**Personne physique** : un être humain, doté de la personnalité juridique de la naissance à la mort.","**Personne morale** : un groupement (société, association) qui a sa propre existence juridique.","**Capacité** : à 25 ans, elle est majeure et capable → elle peut contracter seule."]},{t:"tip",h:"À retenir",c:"La société est une **personne morale** : son patrimoine est distinct de celui de ses associés."}]}]},"p1-droit-t4":{sections:[{h:"⚖️ Exemple — une maison et une vie privée : droits patrimoniaux et extrapatrimoniaux",group:"cas",blocks:[{t:"example",h:"Cas",c:"Une personne possède une maison (bien) et a droit au respect de sa vie privée."},{t:"list",c:["**Droits patrimoniaux** : ils ont une valeur en argent et peuvent se vendre/transmettre (propriété, créances).","**Droits extrapatrimoniaux** : ils n’ont pas de prix et sont attachés à la personne (droit à la vie privée, à l’image, au nom).","Les seconds sont **incessibles** : on ne peut pas les vendre."]},{t:"tip",h:"À distinguer",c:"Patrimonial = « chiffrable et cessible » ; extrapatrimonial = « attaché à la personne, non monnayable »."}]}]}},v=Object.freeze(Object.defineProperty({__proto__:null,default:u},Symbol.toStringTag,{value:"Module"})),c={"p1-droit-t2":{id:"p1-droit-t2-doc",type:"doc",title:"Étude de documents — Le litige, la preuve et le procès",icon:"📑",intro:"Comprendre à qui incombe la preuve et comment se déroule un procès. Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — La charge de la preuve",text:"En principe, c’est au **demandeur** — celui qui réclame l’exécution d’une obligation — d’en apporter la **preuve** : « Celui qui réclame l’exécution d’une obligation doit la prouver. » La preuve doit être obtenue **loyalement**."},{id:2,title:"Document 2 — Preuves parfaites et imparfaites",text:`Les modes de preuve se classent selon leur force :
• les **preuves parfaites**, dont la valeur est **fixée par la loi** et qui **s’imposent au juge** : l’**acte authentique** (reçu par un officier public, ex. un notaire), l’**acte sous signature privée** (écrit signé par les parties), l’**aveu** et le **serment** ;
• les **preuves imparfaites**, laissées à la **libre appréciation** du juge : le **témoignage**, l’**indice**, la **présomption**.`},{id:3,title:"Document 3 — Le déroulement d’une instance",text:"En matière civile, le procès s’ouvre souvent par une **assignation** (acte convoquant le défendeur). L’affaire est examinée lors d’une **audience**, puis les juges se retirent en **délibéré**. La décision s’appelle un **jugement** (tribunal) ou un **arrêt** (cour d’appel, Cour de cassation)."},{id:4,title:"Document 4 — Le litige de Sophie",text:"Sophie a prêté 3 000 € à un ami. Elle possède une **reconnaissance de dette écrite et signée** par lui. L’ami refuse de rembourser et prétend que « c’était un cadeau ». Sophie décide de saisir le tribunal."}],questions:[{doc:1,q:"En principe, la charge de la preuve pèse sur…",choices:["le demandeur","le juge","le témoin","le défendeur"],answer:0,explain:"C’est à celui qui réclame de prouver."},{doc:2,q:"Un acte notarié (acte authentique) est une preuve…",choices:["parfaite","imparfaite","interdite","orale"],answer:0,explain:"Sa valeur est fixée par la loi et s’impose au juge."},{doc:2,q:"Un témoignage est une preuve…",choices:["imparfaite (libre appréciation du juge)","parfaite","qui s’impose au juge","authentique"],answer:0,explain:"Les preuves imparfaites sont librement appréciées."},{doc:3,q:"Une décision rendue par une cour d’appel s’appelle…",choices:["un arrêt","un jugement","une assignation","un délibéré"],answer:0,explain:"Tribunal → jugement ; cour d’appel / Cour de cassation → arrêt."},{doc:[1,2,4],q:"Grâce à sa reconnaissance de dette signée, Sophie dispose…",choices:["d’une preuve parfaite (acte sous signature privée)","d’un simple témoignage","d’aucune preuve","d’un aveu de sa part"],answer:0,explain:"Un écrit signé par le débiteur est un acte sous signature privée : preuve parfaite."},{doc:1,type:"redac",q:"Explique sur qui pèse la charge de la preuve et pourquoi c’est important.",answer:"La charge de la preuve pèse sur le **demandeur** : celui qui **réclame** l’exécution d’une obligation doit prouver qu’elle existe. C’est important car, faute de preuve, le demandeur perd son procès même s’il a raison sur le fond : « ne pas pouvoir prouver son droit, c’est comme ne pas l’avoir ». D’où l’intérêt de conserver des écrits."},{doc:[2,4],type:"redac",q:"La reconnaissance de dette de Sophie a-t-elle plus de valeur que la parole de l’ami ? Justifie.",answer:"Oui. La reconnaissance de dette est un **écrit signé** par le débiteur : c’est un **acte sous signature privée**, donc une **preuve parfaite** dont la valeur est fixée par la loi et **s’impose au juge**. La simple affirmation de l’ami (« c’était un cadeau ») n’est pas prouvée et ne suffit pas à écarter cet écrit. Sophie est donc en position favorable pour obtenir le remboursement."},{doc:3,type:"redac",q:"Décris brièvement les étapes du procès civil que va suivre l’affaire de Sophie.",answer:"Sophie va d’abord faire **assigner** son ami (acte qui l’informe du procès et le convoque). L’affaire sera ensuite examinée lors d’une **audience**, où chacun présente ses arguments et ses preuves. Les juges se retireront en **délibéré**, puis rendront un **jugement**. Si l’une des parties n’est pas satisfaite, elle pourra faire **appel**, la cour d’appel rendant alors un **arrêt**."}]},"p1-droit-t1":{id:"p1-droit-t1-doc",type:"doc",title:"Étude de documents — La règle de droit et ses sources",icon:"📑",intro:"Qu’est-ce qui distingue une règle de droit des autres règles, et comment s’organisent les sources ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — Les caractères de la règle de droit",text:"La règle de droit présente quatre caractères : elle est **générale** (elle s’applique à tous), **impersonnelle** (elle ne vise personne nommément), **obligatoire** et **coercitive** (assortie de la **contrainte / sanction de l’État** en cas de non-respect). Ses fonctions : organiser la société, pacifier les relations, protéger les personnes et sanctionner les manquements."},{id:2,title:"Document 2 — Règle de droit et règle morale",text:"La règle **morale** relève de la conscience individuelle ; la règle **religieuse** relève de la croyance. Ni l’une ni l’autre n’est assortie de la **contrainte de l’État**. C’est précisément ce caractère **coercitif** (la sanction étatique) qui distingue la règle de droit de ces autres règles de conduite."},{id:3,title:"Document 3 — La hiérarchie des normes",text:"Les sources du droit sont hiérarchisées : au sommet la **Constitution** (bloc de constitutionnalité), puis les **traités internationaux et le droit de l’Union européenne**, puis les **lois** (votées par le Parlement), enfin les **règlements** (décrets, arrêtés). Une norme inférieure doit respecter les normes supérieures. Le **Conseil constitutionnel** en contrôle le respect ; depuis 2010, la **QPC** permet à un justiciable de contester une loi en vigueur."},{id:4,title:"Document 4 — L’arrêté du maire",text:"Un maire prend un **arrêté** (un règlement municipal) interdisant totalement et en toute circonstance de manifester dans sa commune. Un habitant conteste cet arrêté, estimant qu’il porte atteinte à la liberté de manifester garantie par la Constitution."}],questions:[{doc:1,q:"La règle de droit est générale, impersonnelle, obligatoire et…",choices:["coercitive","facultative","secrète","religieuse"],answer:0,explain:"Coercitive : assortie de la contrainte / sanction de l’État. C’est le 4ᵉ caractère."},{doc:2,q:"Ce qui distingue une règle de droit d’une règle morale, c’est…",choices:["son caractère coercitif (la sanction de l’État)","sa longueur","son ancienneté","sa langue"],answer:0,explain:"La morale relève de la conscience : elle n’est pas assortie de la contrainte étatique."},{doc:3,q:"Au sommet de la hiérarchie des normes se trouve…",choices:["la Constitution","un arrêté municipal","une loi ordinaire","un contrat"],answer:0,explain:"La Constitution prime sur toutes les autres normes."},{doc:3,q:"La QPC permet à un justiciable de…",choices:["contester une loi qu’il juge contraire à la Constitution","écrire une nouvelle loi","juger un crime","signer un contrat"],answer:0,explain:"Question Prioritaire de Constitutionnalité (depuis 2010)."},{doc:[3,4],q:"L’arrêté du maire est illégal car…",choices:["une norme inférieure doit respecter la loi et la Constitution","un maire ne peut jamais prendre d’arrêté","la manifestation est interdite partout","l’arrêté est trop court"],answer:0,explain:"L’arrêté (règlement) ne peut contredire la Constitution, norme supérieure."},{doc:[1,2],type:"redac",q:"Qu’est-ce qui distingue la règle de droit d’une simple règle morale ?",answer:"La règle de droit partage certains caractères avec la règle morale (elle guide les conduites), mais elle est **générale, impersonnelle, obligatoire** et surtout **coercitive** : elle est assortie de la **contrainte / sanction de l’État**. La règle **morale**, elle, relève de la **conscience** et n’est pas sanctionnée par la puissance publique. C’est donc ce caractère **coercitif** (la sanction étatique) qui distingue le droit de la morale."},{doc:[3,4],type:"redac",q:"En t’appuyant sur la hiérarchie des normes, explique pourquoi l’arrêté du maire peut être annulé.",answer:"La **hiérarchie des normes** impose qu’une norme inférieure respecte les normes supérieures. L’**arrêté** du maire est un **règlement**, tout en bas de la pyramide : il doit respecter la **loi** et la **Constitution**, qui garantissent la liberté de manifester. Une interdiction **générale et absolue** est disproportionnée et **contraire** à ces normes supérieures : le juge administratif peut donc **annuler** l’arrêté. La hiérarchie des normes protège ainsi les libertés."},{doc:1,type:"redac",q:"Cite et explique deux fonctions du droit.",answer:"Le droit **organise** la société et l’activité économique (il fixe des règles communes) et **pacifie** les relations en évitant la loi du plus fort (il permet de régler les conflits par le juge plutôt que par la force). On peut aussi citer sa fonction de **protection** des personnes et de leurs droits, et sa fonction de **sanction** des manquements."}]},"p1-droit-t3":{id:"p1-droit-t3-doc",type:"doc",title:"Étude de documents — Les personnes et leur capacité",icon:"📑",intro:"Qui est sujet de droit et dans quelle mesure peut-on agir seul ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — La personnalité juridique",text:"La **personnalité juridique** est l’aptitude à être **titulaire de droits et d’obligations**. Elle est reconnue aux **personnes physiques** (les êtres humains, de la naissance à la mort, identifiés par un nom et un domicile) et aux **personnes morales** (groupements — société, association déclarée, État — dotés d’un patrimoine propre distinct de celui de leurs membres)."},{id:2,title:"Document 2 — La capacité juridique",text:"On distingue la **capacité de jouissance** (avoir des droits) de la **capacité d’exercice** (pouvoir les exercer seul). Certaines personnes sont **incapables** et doivent être **représentées** ou **assistées** : les **mineurs** non émancipés (représentés par leurs parents) et les **majeurs protégés** (sauvegarde de justice, curatelle, tutelle)."},{id:3,title:"Document 3 — Le patrimoine",text:"Le **patrimoine** est l’ensemble des **droits et obligations** d’une personne **évaluables en argent** : un **actif** (les biens) et un **passif** (les dettes). Principe d’**unicité** : toute personne a un patrimoine, et un seul. On distingue les droits **patrimoniaux** (cessibles, saisissables) des droits **extrapatrimoniaux** (vie privée, image, nom)."},{id:4,title:"Document 4 — Le scooter de Tom",text:"Tom, **16 ans** (mineur non émancipé), achète seul un scooter d’occasion à 1 500 € auprès d’un particulier, sans en parler à ses parents. Ceux-ci, mécontents, souhaitent revenir sur cette opération."}],questions:[{doc:1,q:"La personnalité juridique est l’aptitude à…",choices:["être titulaire de droits et d’obligations","voter une loi","juger un litige","produire des biens"],answer:0,explain:"Elle fait de l’être un sujet de droit."},{doc:1,q:"Une association déclarée est une personne…",choices:["morale","physique","sans patrimoine","incapable"],answer:0,explain:"Elle a un patrimoine propre, distinct de celui de ses membres."},{doc:2,q:"Pouvoir exercer soi-même ses droits, c’est la capacité…",choices:["d’exercice","de jouissance","de propriété","d’ester"],answer:0,explain:"Jouissance = avoir des droits ; exercice = les exercer seul."},{doc:3,q:"Le droit à l’image est un droit…",choices:["extrapatrimonial","patrimonial","cessible","saisissable"],answer:0,explain:"Les droits de la personnalité sont extrapatrimoniaux."},{doc:[2,4],q:"L’achat du scooter par Tom peut être remis en cause car…",choices:["mineur, il n’a pas la pleine capacité d’exercice pour un tel acte","un mineur n’a aucun droit","le scooter est trop cher pour exister","les parents sont incapables"],answer:0,explain:"Le mineur doit être représenté pour les actes importants."},{doc:1,type:"redac",q:"Distingue la personne physique de la personne morale.",answer:"La **personne physique** est un **être humain**, sujet de droit de la **naissance à la mort**, identifié par un nom et un domicile. La **personne morale** est un **groupement** (société, association déclarée, État) auquel la loi reconnaît la personnalité juridique : elle a un **nom**, un **siège** et surtout un **patrimoine propre**, distinct de celui de ses membres, et peut agir en justice."},{doc:[2,4],type:"redac",q:"Les parents de Tom peuvent-ils faire annuler l’achat du scooter ? Justifie.",answer:"Oui, en principe. Tom, **mineur non émancipé**, a la **capacité de jouissance** (il peut être propriétaire) mais pas la pleine **capacité d’exercice** : l’achat d’un scooter à 1 500 € est un **acte de disposition** qui dépasse la gestion courante d’un mineur. Ses **parents**, qui le **représentent**, peuvent donc demander l’**annulation** de la vente. En revanche, un acte de la vie courante (acheter une place de cinéma) resterait valable."},{doc:3,type:"redac",q:"Qu’est-ce que le patrimoine ? Explique le principe d’unicité.",answer:"Le **patrimoine** est l’ensemble des **droits et obligations** d’une personne **évaluables en argent** : un **actif** (ses biens) et un **passif** (ses dettes). Le principe d’**unicité** signifie que **toute personne a un patrimoine, et un seul** : ses biens répondent de ses dettes. La loi admet toutefois des exceptions (patrimoine d’affectation) pour protéger le patrimoine personnel de l’entrepreneur."}]},"p1-droit-t4":{id:"p1-droit-t4-doc",type:"doc",title:"Étude de documents — Propriété, création et vie privée",icon:"📑",intro:"Comment le droit protège-t-il les biens, les créations et la personne ? Lis les documents puis réponds.",documents:[{id:1,title:"Document 1 — Le droit de propriété",text:"Le droit de propriété comporte trois attributs : l’**usus** (utiliser le bien), le **fructus** (en percevoir les revenus, ex. un loyer) et l’**abusus** (en disposer : vendre, détruire). On lui reconnaît trois caractères : **absolu, exclusif et perpétuel**. Il connaît toutefois des **limites** : intérêt général et respect du voisinage."},{id:2,title:"Document 2 — Le trouble anormal du voisinage",text:"Nul ne doit causer à autrui un **trouble anormal du voisinage**. Des nuisances excessives (bruit, odeurs, fumées) qui dépassent les inconvénients normaux de la vie en collectivité engagent la **responsabilité** de leur auteur, même s’il ne commet aucune faute : c’est une **limite** au droit de propriété."},{id:3,title:"Document 3 — La propriété intellectuelle",text:"Les créations sont protégées. La **propriété industrielle** protège la **marque** (signe distinctif) et le **brevet** (invention), en conférant un **monopole d’exploitation** ; toute copie constitue une **contrefaçon**, sanctionnée par une **action en contrefaçon**. Le **droit d’auteur** protège les œuvres et comprend un **droit moral** (respect de l’œuvre) et des **droits patrimoniaux** (en tirer des revenus)."},{id:4,title:"Document 4 — La photo de Sarah",text:"Un ami publie sur un réseau social une photo de Sarah, prise en soirée, **sans lui demander son accord**. Sarah, gênée, veut obtenir le retrait de la photo. Le droit au respect de la **vie privée** et le **droit à l’image** sont des droits de la personnalité ; le **RGPD** encadre l’usage des données personnelles, sous le contrôle de la **CNIL**."}],questions:[{doc:1,q:"Le droit de percevoir les revenus d’un bien (ex. un loyer) est…",choices:["le fructus","l’usus","l’abusus","l’usufruit"],answer:0,explain:"Usus = utiliser ; fructus = revenus ; abusus = disposer."},{doc:1,q:"Les caractères du droit de propriété sont…",choices:["absolu, exclusif, perpétuel","général, impersonnel, obligatoire","certain, direct, personnel","oral, écrit, tacite"],answer:0,explain:"Trois caractères, avec toutefois des limites."},{doc:3,q:"Reproduire une marque sans autorisation constitue…",choices:["une contrefaçon","un trouble du voisinage","un acte authentique","une preuve parfaite"],answer:0,explain:"La contrefaçon est sanctionnée par une action en contrefaçon."},{doc:4,q:"En France, l’organisme qui veille à la protection des données personnelles est…",choices:["la CNIL","la Cour de cassation","l’INSEE","l’Autorité de la concurrence"],answer:0,explain:"La CNIL applique le RGPD."},{doc:[2,1],q:"Un voisin qui cause un bruit excessif et permanent…",choices:["dépasse les limites du droit de propriété (trouble anormal)","exerce normalement sa propriété","commet une contrefaçon","exerce son fructus"],answer:0,explain:"Le trouble anormal du voisinage est une limite au droit de propriété."},{doc:1,type:"redac",q:"Présente les trois attributs du droit de propriété avec un exemple pour chacun.",answer:"Le droit de propriété comporte : l’**usus** — le droit d’**utiliser** le bien (habiter sa maison) ; le **fructus** — le droit d’en **percevoir les revenus** (louer la maison et encaisser le loyer) ; l’**abusus** — le droit d’en **disposer** (vendre ou détruire le bien). Réunis, ces trois attributs font du propriétaire le maître le plus complet de son bien, sous réserve des limites (voisinage, intérêt général)."},{doc:[3],type:"redac",q:"Distingue la propriété industrielle du droit d’auteur.",answer:"La **propriété industrielle** protège les créations utiles à l’activité économique — la **marque** (signe distinctif) et le **brevet** (invention) — en conférant un **monopole d’exploitation**, et suppose un dépôt. Le **droit d’auteur** protège les **œuvres de l’esprit** (livre, musique, logiciel) **dès leur création**, sans formalité ; il comprend un **droit moral** (perpétuel, respect de l’œuvre et du nom) et des **droits patrimoniaux** (exploiter l’œuvre et en tirer des revenus)."},{doc:4,type:"redac",q:"Sarah peut-elle exiger le retrait de la photo publiée sans son accord ? Justifie.",answer:"Oui. Le **droit à l’image** et le droit au respect de la **vie privée** sont des **droits de la personnalité**, **inaliénables** : publier l’image d’une personne suppose son **accord**. Comme Sarah n’a pas consenti, elle peut exiger le **retrait** de la photo et, en cas de préjudice, une réparation. Le **RGPD** lui donne en outre un droit à l’**effacement** de ses données, dont la **CNIL** garantit le respect."}]}},b=Object.freeze(Object.defineProperty({__proto__:null,default:c},Symbol.toStringTag,{value:"Module"})),d={"p1-droit-t1-doc":2,"p1-droit-t1-flash":0,"p1-droit-t1-ordre":2,"p1-droit-t1-qcm":1,"p1-droit-t1-vf":3,"p1-droit-t2-doc":1,"p1-droit-t2-flash":0,"p1-droit-t2-qcm":2,"p1-droit-t2-tri":1,"p1-droit-t3-doc":1,"p1-droit-t3-flash":1,"p1-droit-t3-qcm":0,"p1-droit-t3-tri":2,"p1-droit-t4-assoc":0,"p1-droit-t4-doc":1,"p1-droit-t4-flash":1,"p1-droit-t4-qcm":2,"p1-droit-t4-vf":1},f=Object.freeze(Object.defineProperty({__proto__:null,default:d},Symbol.toStringTag,{value:"Module"})),e="p1-droit",i="Droit",t="Droit",r="⚖️",n="#b45309",s="premiere",a="Les fondamentaux : la règle, le litige, les personnes, les droits.",o=[{id:"p1-droit-t1",name:"Thème 1 — Qu’est-ce que le droit ?",short:"Qu’est-ce que le droit ?",keywords:"droit fonctions État de droit laïcité ordre public règle de droit générale impersonnelle obligatoire coercitive contrainte sanction étatique règle morale religieuse sources hiérarchie des normes Constitution traités UE lois règlements jurisprudence coutume Cour de cassation Conseil constitutionnel QPC contrôle de constitutionnalité droit privé public",intro:"Le droit, ce sont les **règles qui organisent la vie en société** et que l’État fait respecter. Sans droit, ce serait la loi du plus fort. On découvre ses **fonctions**, les **caractères** de la règle et les **sources** qui la produisent.",cours:[{h:"Les fonctions du droit et l’État de droit",blocks:[{t:"p",c:"Le droit est l’ensemble des **règles générales et obligatoires** qui régissent les rapports entre les personnes, dont le respect est **garanti par la puissance publique** (l’État). Ses **fonctions** :"},{t:"list",c:["**organiser** la société et l’activité économique,","**pacifier** et **sécuriser** les relations (éviter la loi du plus fort),","**protéger** les personnes et leurs droits,","**arbitrer** les conflits et **sanctionner** les manquements."]},{t:"p",c:"Dans un **État de droit**, la puissance publique elle-même est **soumise au droit** : personne n’est au-dessus de la loi. Deux principes structurants s’y rattachent :"},{t:"list",c:["la **laïcité** : l’État est neutre en matière religieuse et garantit la liberté de conscience ;","l’**ordre public** : l’ensemble des règles essentielles (sécurité, salubrité, tranquillité, dignité) auxquelles on ne peut pas déroger par contrat."]}]},{h:"Les caractères de la règle de droit",blocks:[{t:"p",c:"Une règle de droit est **générale** (elle s’applique à tous), **impersonnelle** (elle ne vise personne nommément), **obligatoire** et **coercitive** (assortie de la **contrainte / sanction de l’État** en cas de non-respect)."},{t:"warning",c:"C’est ce caractère **coercitif** (la **contrainte étatique**) qui la distingue d’une **règle morale** (qui relève de la conscience) ou **religieuse** (qui relève de la croyance) : celles-ci ne sont pas sanctionnées par l’État."}]},{h:"Les sources du droit et la hiérarchie des normes",blocks:[{t:"p",c:"Les règles proviennent de plusieurs **sources**, hiérarchisées : une norme inférieure doit **respecter** les normes supérieures."},{t:"table",head:["Niveau","Source"],rows:[["1","Bloc de constitutionnalité (la Constitution, la DDHC…)"],["2","Traités internationaux et droit de l’Union européenne"],["3","La loi (votée par le Parlement)"],["4","Les règlements (décrets, arrêtés)"]]},{t:"p",c:"Le **droit de l’Union européenne** occupe une place importante : ses **règlements** et **directives** s’imposent aux États membres. S’ajoutent des sources **non écrites** : la **jurisprudence** (décisions des tribunaux qui interprètent la règle) et la **coutume** (usages anciens et acceptés)."},{t:"p",c:"Le respect de la hiérarchie est contrôlé : le **Conseil constitutionnel** vérifie qu’une loi est conforme à la Constitution. Depuis 2010, tout justiciable peut soulever une **QPC** (Question Prioritaire de Constitutionnalité) pour contester une loi déjà en vigueur. Au sommet de l’ordre judiciaire, la **Cour de cassation** unifie l’interprétation du droit."},{t:"example",h:"Un maire face à la hiérarchie des normes",c:`Un maire prend un **arrêté** (un règlement) interdisant totalement de manifester dans sa commune. Un habitant le conteste. 
→ L’arrêté est une **norme inférieure** : il doit respecter la **loi** et la **Constitution**, qui garantissent la liberté de manifester. Une interdiction générale et absolue est donc **illégale** : le juge administratif peut l’annuler. La **hiérarchie des normes** protège ainsi les libertés.`}]},{h:"Droit privé et droit public",blocks:[{t:"p",c:"Grande distinction : le **droit privé** régit les rapports entre **particuliers** (droit civil, commercial, du travail) ; le **droit public** régit l’**État** et ses rapports avec les citoyens (droit constitutionnel, administratif)."}]}],essentiel:["Fonctions du droit : **organiser, pacifier, protéger, sanctionner** ; dans l’**État de droit**, l’État est soumis au droit (+ **laïcité**, **ordre public**).","Règle de droit = **générale, impersonnelle, obligatoire, coercitive** (contrainte / sanction de l’État) (≠ règle morale/religieuse).","Sources : **Constitution > traités/UE > lois > règlements** (+ jurisprudence, coutume) ; contrôle par le **Conseil constitutionnel** et la **QPC**.","**Droit privé** (particuliers) vs **droit public** (État)."],resources:[{kind:"video",label:"Qu’est-ce que le droit ? Fonctions et sources",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=qu%20est%20ce%20que%20le%20droit%20fonctions%20r%C3%A8gle%20sources%20hi%C3%A9rarchie%20des%20normes%20premi%C3%A8re%20STMG"},{kind:"video",label:"État de droit, hiérarchie des normes, QPC",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=%C3%89tat%20de%20droit%20hi%C3%A9rarchie%20des%20normes%20QPC%20Conseil%20constitutionnel%20premi%C3%A8re%20STMG"}],games:[{id:"p1-droit-t1-qcm",type:"qcm",title:"QCM — La règle de droit",icon:"❓",questions:[{q:"La règle de droit est générale, impersonnelle, obligatoire et…",choices:["coercitive","facultative","religieuse","secrète"],answer:0,explain:"Coercitive : elle est assortie de la contrainte / sanction de l’État en cas de non-respect. C’est le 4ᵉ caractère."},{q:"Ce qui distingue une règle de droit d’une règle morale, c’est…",choices:["son caractère coercitif (la sanction de l’État)","sa longueur","son ancienneté","sa langue"],answer:0,explain:"La règle morale relève de la conscience : elle n’est pas assortie de la contrainte étatique."},{q:"Dans un État de droit…",choices:["l’État lui-même est soumis au droit","l’État est au-dessus des lois","seuls les citoyens obéissent au droit","le droit n’existe pas"],answer:0,explain:"Personne n’est au-dessus de la loi, pas même la puissance publique."},{q:"La neutralité de l’État en matière religieuse s’appelle…",choices:["la laïcité","l’ordre public","la jurisprudence","la coutume"],answer:0,explain:"La laïcité garantit la liberté de conscience et la neutralité de l’État."},{q:"Au sommet de la hiérarchie des normes :",choices:["la Constitution","un arrêté municipal","un contrat","un règlement intérieur"],answer:0,explain:"La Constitution (bloc de constitutionnalité) prime sur toutes les autres normes."},{q:"La QPC permet à un justiciable de…",choices:["contester une loi qu’il juge contraire à la Constitution","écrire une nouvelle loi","juger un crime","signer un contrat"],answer:0,explain:"La Question Prioritaire de Constitutionnalité conduit au Conseil constitutionnel."},{q:"L’ensemble des décisions des tribunaux qui interprètent la règle s’appelle…",choices:["la jurisprudence","la coutume","la doctrine","la loi"],answer:0,explain:"La jurisprudence précise et interprète la règle de droit."},{q:"Le droit du travail relève du droit…",choices:["privé","public","constitutionnel","international"],answer:0,explain:"Le droit privé régit les rapports entre particuliers (dont employeur/salarié)."}]},{id:"p1-droit-t1-ordre",type:"ordre",title:"Remise en ordre — Hiérarchie des normes",icon:"🔢",instruction:"Classe les sources **écrites** de la plus élevée à la plus basse.",steps:["Constitution","Traités et droit de l’UE","Lois","Règlements (décrets, arrêtés)"],explain:"Constitution > traités/UE > lois > règlements. La **jurisprudence** et la **coutume** sont aussi des sources du droit, mais **non écrites** : elles n’apparaissent pas dans cette hiérarchie des normes écrites (d’où leur absence ici), ce qui n’enlève rien à leur valeur de source."},{id:"p1-droit-t1-vf",type:"vraifaux",title:"Vrai / Faux rapide",icon:"⚡",questions:[{statement:"Une règle de droit vise une personne en particulier.",answer:!1,explain:"Faux : elle est générale et impersonnelle."},{statement:"Dans un État de droit, l’État est soumis au droit.",answer:!0,explain:"Vrai : nul n’est au-dessus de la loi."},{statement:"La jurisprudence est une source du droit.",answer:!0,explain:"Vrai : les décisions des tribunaux interprètent la règle. C’est une source **non écrite** (comme la coutume) : elle ne figure pas dans la hiérarchie des normes écrites, mais reste bien une source du droit."},{statement:"Une loi doit être conforme à la Constitution.",answer:!0,explain:"Vrai : dans la hiérarchie des normes, la loi doit respecter la Constitution (contrôle du Conseil constitutionnel, QPC)."}]},{id:"p1-droit-t1-flash",type:"flashcard",title:"Flashcards — La règle de droit",icon:"🃏",cards:[{front:"Fonctions du droit",back:"Organiser, pacifier/sécuriser, protéger, arbitrer et sanctionner."},{front:"État de droit",back:"La puissance publique est elle-même soumise au droit."},{front:"Laïcité / ordre public",back:"Neutralité religieuse de l’État / règles essentielles auxquelles on ne peut déroger."},{front:"Caractères de la règle de droit",back:"Générale, impersonnelle, obligatoire, coercitive (contrainte / sanction de l’État)."},{front:"Hiérarchie des normes",back:"Constitution > traités/UE > lois > règlements."},{front:"QPC",back:"Question Prioritaire de Constitutionnalité : contester une loi en vigueur."}]}]},{id:"p1-droit-t2",name:"Thème 2 — Comment le droit permet-il de régler un litige ?",short:"Le litige",keywords:"litige demandeur défendeur prétentions acte juridique fait juridique preuve charge de la preuve objet preuve parfaite imparfaite acte authentique acte sous signature privée aveu serment témoignage présomption preuve électronique organisation judiciaire ordre judiciaire administratif juridictions civiles pénales procès civil pénal instance assignation audience délibéré jugement arrêt mise en examen partie civile premier degré appel pourvoi cassation accord amiable CJUE CEDH",intro:"Quand un désaccord dégénère, il devient un **litige**. Le droit offre des moyens de le résoudre : d’abord en **prouvant** son droit, puis, si besoin, en **saisissant le juge** — dont les décisions peuvent faire l’objet de **voies de recours**.",cours:[{h:"Le litige : demandeur, défendeur et prétentions",blocks:[{t:"p",c:"Un **litige** est un **désaccord juridique** entre deux parties aux **prétentions** opposées. Devant le juge, celui ou celle qui saisit la justice pour réclamer un droit est le **demandeur** (au féminin : la **demanderesse**) ; celui ou celle contre qui l’action est dirigée est le **défendeur** (la **défenderesse**)."},{t:"p",c:"À l’origine des droits et obligations, on distingue :"},{t:"table",head:["Acte juridique","Fait juridique"],rows:[["Volonté de produire des effets de droit","Événement qui produit des effets de droit sans les avoir voulus"],["Ex. un contrat, un testament","Ex. un accident, un dommage, une naissance"]]}]},{h:"La preuve : charge, objet et modes",blocks:[{t:"p",c:"Pour faire valoir un droit, il faut le **prouver**. La **charge de la preuve** pèse sur le **demandeur** : c’est à celui qui réclame l’exécution d’une obligation d’en apporter la preuve. La preuve doit porter sur l’**objet** du litige et être obtenue **loyalement**."},{t:"p",c:"On classe les modes de preuve en deux catégories selon leur **force probante** :"},{t:"table",head:["Preuves parfaites","Preuves imparfaites"],rows:[["Valeur fixée par la loi : elles s’imposent au juge, qui doit les admettre","Laissées à la libre appréciation du juge (intime conviction)"],["Acte authentique, acte sous signature privée, aveu judiciaire, serment","Témoignage, indice, présomption"]]},{t:"warning",c:"Attention : une preuve parfaite n’est pas « n’importe quel écrit ». C’est un mode de preuve dont la **valeur est déterminée par la loi**. L’**acte authentique** est reçu par un **officier public** (ex. un notaire) ; l’**acte sous signature privée** est un écrit **signé par les parties**. La **preuve électronique** est admise si l’on peut identifier son auteur et en garantir l’intégrité."},{t:"tip",c:"D’où l’importance de conserver des **écrits** (contrats, reçus, factures), surtout pour les engagements importants."}]},{h:"Le recours au juge : l’organisation judiciaire",blocks:[{t:"p",c:"La justice est organisée en **deux ordres** :"},{t:"list",c:["**Ordre judiciaire** : litiges entre particuliers (**juridictions civiles**) et infractions (**juridictions pénales**).","**Ordre administratif** : litiges impliquant l’**administration**."]},{t:"p",c:"Il faut distinguer le **procès civil** (il oppose des particuliers et vise à **réparer** : dommages et intérêts) du **procès pénal** (il vise à **sanctionner** une infraction au nom de la société)."}]},{h:"Le déroulement d’une instance : assignation, audience, jugement",blocks:[{t:"p",c:"Une fois le tribunal saisi, l’affaire suit une **instance** (la procédure en cours). En matière civile, le procès débute souvent par une **assignation** : l’acte par lequel le demandeur informe le défendeur qu’un procès est engagé et le convoque devant le juge. L’affaire est examinée lors d’une **audience** (où les parties, souvent par leurs avocats, présentent leurs arguments), puis les juges se retirent en **délibéré** pour rendre leur décision."},{t:"p",c:"La décision s’appelle un **jugement** (rendu par un tribunal) ou un **arrêt** (rendu par une cour d’appel ou la Cour de cassation). En matière pénale, une personne soupçonnée peut être **mise en examen** lorsqu’il existe contre elle des indices graves ou concordants ; la victime peut se constituer **partie civile** pour demander, au cours du procès pénal, la réparation de son préjudice."},{t:"example",h:"Un litige de voisinage",c:"Léa (la **demanderesse**) reproche à son voisin (le **défendeur**) un dégât des eaux. Elle le fait **assigner** devant le tribunal judiciaire : l’**instance** est ouverte. Lors de l’**audience**, chacun présente ses **preuves**. Après le **délibéré**, le tribunal rend un **jugement** condamnant le voisin à l’indemniser. Mécontent, celui-ci fait **appel** : la cour d’appel rejugera l’affaire et rendra un **arrêt**."}]},{h:"Les voies de recours et l’accord amiable",blocks:[{t:"p",c:"Une décision de justice peut être contestée par les **voies de recours** :"},{t:"list",c:["**premier degré** : le tribunal juge l’affaire (les faits et le droit) ;","**appel** : une **cour d’appel** rejuge entièrement l’affaire (faits + droit) ;","**pourvoi en cassation** : la **Cour de cassation** vérifie seulement la **bonne application du droit**, sans rejuger les faits."]},{t:"p",c:"Un litige peut aussi se terminer par un **accord amiable** entre les parties, sans aller jusqu’au jugement. Enfin, deux **juridictions européennes** peuvent intervenir : la **CJUE** (Cour de justice de l’Union européenne, respect du droit de l’UE) et la **CEDH** (Cour européenne des droits de l’homme, respect des libertés fondamentales)."}]}],essentiel:["**Litige** = désaccord aux prétentions opposées ; **demandeur** (qui réclame) vs **défendeur**.","**Acte juridique** (volonté, ex. contrat) vs **fait juridique** (événement non voulu, ex. accident).","**Charge de la preuve** sur le **demandeur** ; **preuves parfaites** (valeur fixée par la loi : acte authentique, acte sous signature privée, aveu, serment) vs **imparfaites** (témoignage, indice, présomption).","Deux ordres (**judiciaire** civil/pénal, **administratif**) ; voies de recours : **1er degré → appel → pourvoi en cassation** (+ CJUE, CEDH)."],resources:[{kind:"video",label:"Le litige et la preuve",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=litige%20charge%20de%20la%20preuve%20preuve%20parfaite%20imparfaite%20premi%C3%A8re%20STMG%20droit"},{kind:"video",label:"Organisation judiciaire et voies de recours",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=organisation%20judiciaire%20ordre%20judiciaire%20administratif%20appel%20cassation%20premi%C3%A8re%20STMG"}],games:[{id:"p1-droit-t2-qcm",type:"qcm",title:"QCM — Le litige",icon:"❓",questions:[{q:"La charge de la preuve pèse en principe sur…",choices:["le demandeur","le juge","le témoin","le défendeur"],answer:0,explain:"C’est au demandeur, celui qui réclame l’exécution d’une obligation, de prouver."},{q:"Un contrat, conclu volontairement pour produire des effets de droit, est un…",choices:["acte juridique","fait juridique","témoignage","pourvoi"],answer:0,explain:"Acte juridique = manifestation de volonté ; le fait juridique (ex. accident) n’est pas voulu."},{q:"Une preuve parfaite se définit par le fait que…",choices:["sa valeur est fixée par la loi et s’impose au juge","c’est n’importe quel écrit","c’est un simple témoignage","le juge peut l’ignorer"],answer:0,explain:"Acte authentique, acte sous signature privée, aveu, serment : le juge doit les admettre."},{q:"Un témoignage ou un indice est une preuve…",choices:["imparfaite (libre appréciation du juge)","parfaite","interdite","authentique"],answer:0,explain:"Les preuves imparfaites sont appréciées librement par le juge (intime conviction)."},{q:"Un litige avec l’administration relève de l’ordre…",choices:["administratif","judiciaire","pénal","européen"],answer:0,explain:"L’ordre administratif juge les litiges impliquant l’administration."},{q:"La Cour de cassation…",choices:["vérifie la bonne application du droit (sans rejuger les faits)","rejuge entièrement l’affaire","écrit les lois","gère l’administration"],answer:0,explain:"Elle contrôle le droit ; l’appel, lui, rejuge les faits."},{q:"Le procès pénal vise à…",choices:["sanctionner une infraction au nom de la société","réparer un dommage entre particuliers","signer un contrat","écrire une loi"],answer:0,explain:"Le procès civil répare ; le procès pénal sanctionne."}]},{id:"p1-droit-t2-tri",type:"tri",title:"Tri — Preuve parfaite ou imparfaite ?",icon:"🗂️",instruction:"Classe chaque mode de preuve.",categories:[{id:"parf",label:"Preuve parfaite"},{id:"imp",label:"Preuve imparfaite"}],items:[{text:"Un acte notarié (acte authentique)",cat:"parf"},{text:"Un contrat écrit signé par les parties",cat:"parf"},{text:"Le témoignage d’un voisin",cat:"imp"},{text:"Un aveu fait devant le juge",cat:"parf"},{text:"Un simple indice",cat:"imp"}]},{id:"p1-droit-t2-flash",type:"flashcard",title:"Flashcards — Le litige",icon:"🃏",cards:[{front:"Demandeur / demanderesse — défendeur / défenderesse",back:"Celui ou celle qui réclame en justice (demandeur / demanderesse) / celui ou celle contre qui l’action est dirigée (défendeur / défenderesse)."},{front:"Acte / fait juridique",back:"Manifestation de volonté (contrat) / événement non voulu (accident)."},{front:"Charge de la preuve",back:"Elle pèse sur le demandeur."},{front:"Preuve parfaite",back:"Valeur fixée par la loi (acte authentique, acte sous signature privée, aveu, serment) : s’impose au juge."},{front:"Preuve imparfaite",back:"Témoignage, indice, présomption : libre appréciation du juge."},{front:"Déroulement (civil)",back:"Assignation → instance → audience → délibéré → jugement (ou arrêt en appel)."},{front:"Mise en examen / partie civile",back:"Indices graves contre une personne (pénal) / victime qui demande réparation au procès pénal."},{front:"Voies de recours",back:"1er degré → appel (rejuge) → pourvoi en cassation (droit seulement)."}]}]},{id:"p1-droit-t3",name:"Thème 3 — Qui peut faire valoir ses droits ?",short:"Les personnes",keywords:"personnalité juridique personne physique morale nom domicile statut de l’animal capacité jouissance exercice incapacité mineur majeur protégé tutelle curatelle sauvegarde de justice représentation acte de disposition administration patrimoine actif passif unicité universalité indivisibilité incessibilité patrimoine d’affectation droits patrimoniaux extrapatrimoniaux",intro:"Pour avoir des droits, il faut être un **sujet de droit**, c’est-à-dire disposer de la **personnalité juridique**. On étudie qui la possède, dans quelle mesure on peut agir seul (la **capacité**), et ce qu’est le **patrimoine**.",cours:[{h:"La personnalité juridique : personnes physiques et morales, statut de l’animal",blocks:[{t:"p",c:"C’est l’**aptitude à être titulaire de droits et d’obligations**. Elle est reconnue à deux catégories :"},{t:"table",head:["Personne physique","Personne morale"],rows:[["Un être humain","Un groupement (société, association déclarée, État)"],["De la naissance à la mort","Créée par l’immatriculation / la déclaration"],["Identifiée par un nom et un domicile","Identifiée par une dénomination et un siège"]]},{t:"p",c:"Toute personne est identifiée par des **éléments d’état civil** : notamment un **nom** et un **domicile** (le lieu de son principal établissement). Une personne morale a un **patrimoine distinct** de celui de ses membres et peut agir en justice."},{t:"tip",c:"Le **statut de l’animal** : depuis 2015, la loi reconnaît l’animal comme un **être vivant doué de sensibilité** ; il reste toutefois soumis, pour l’essentiel, au **régime des biens**."}]},{h:"La capacité juridique : jouissance, exercice, mineurs et majeurs protégés",blocks:[{t:"p",c:"On distingue la **capacité de jouissance** (avoir des droits) et la **capacité d’exercice** (pouvoir les exercer soi-même). Certaines personnes sont **incapables** et doivent être **représentées** ou **assistées** :"},{t:"list",c:["les **mineurs** / **mineures** non émancipé·es (représenté·es par leurs parents, titulaires de l’autorité parentale) ;","les **majeurs protégés** / **majeures protégées**, selon la gravité : **sauvegarde de justice** (protection légère et temporaire), **curatelle** (le majeur ou la majeure est **assisté·e**), **tutelle** (il ou elle est **représenté·e**). La personne chargée de la mesure est le **tuteur** / la **tutrice** ou le **curateur** / la **curatrice**."]},{t:"p",c:"On distingue aussi les **actes d’administration** (gestion courante, ex. encaisser un loyer) des **actes de disposition** (qui engagent le patrimoine, ex. vendre un bien), pour lesquels la protection est plus forte."},{t:"example",h:"Le scooter de Tom, 16 ans",c:`Tom, **mineur**, achète seul un scooter d’occasion à 1 500 €. 
→ Tom a la **capacité de jouissance** (il peut être propriétaire) mais pas la pleine **capacité d’exercice** : cet **acte de disposition** dépasse la gestion courante d’un mineur. Ses **parents** (ses représentants) peuvent demander l’**annulation** de la vente. En revanche, acheter une place de cinéma (acte de la vie courante) resterait valable.`}]},{h:"Le patrimoine : actif, passif et principes",blocks:[{t:"p",c:"Le **patrimoine** est l’ensemble des **droits et obligations** d’une personne **évaluables en argent** : un **actif** (les biens) et un **passif** (les dettes). Il obéit à des **principes** :"},{t:"list",c:["**unicité** : toute personne a un patrimoine et un seul ;","**universalité** : l’actif répond du passif (les biens garantissent les dettes) ;","**indivisibilité** : le patrimoine forme un tout ;","**incessibilité** : on ne peut céder son patrimoine de son vivant (il se transmet à la mort)."]},{t:"p",c:"Par exception, la loi admet un **patrimoine d’affectation** : une personne peut isoler certains biens pour une activité (ex. l’entrepreneur individuel), afin de **protéger son patrimoine personnel**. Enfin, on distingue les droits **patrimoniaux** des droits **extrapatrimoniaux** :"},{t:"table",head:["Droits patrimoniaux","Droits extrapatrimoniaux"],rows:[["Valeur monétaire, cessibles, saisissables","Hors commerce, attachés à la personne, non cessibles"],["Ex. droit de propriété, créances","Ex. vie privée, image, nom"]]}]}],essentiel:["**Personnalité juridique** = aptitude à être titulaire de droits et d’obligations ; **personne physique** (naissance→mort, nom, domicile) vs **personne morale** (patrimoine propre).","Animal = **être vivant doué de sensibilité**, mais soumis au régime des biens.","**Capacité de jouissance** vs **d’exercice** ; incapables : mineurs, majeurs protégés (**sauvegarde / curatelle / tutelle**).","**Patrimoine** = actif + passif ; principes **unicité, universalité, indivisibilité, incessibilité** (+ **patrimoine d’affectation**)."],resources:[{kind:"video",label:"La personnalité juridique et la capacité",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=personnalit%C3%A9%20juridique%20personne%20physique%20morale%20capacit%C3%A9%20mineur%20majeur%20prot%C3%A9g%C3%A9%20premi%C3%A8re%20STMG"},{kind:"video",label:"Le patrimoine et ses principes",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=patrimoine%20actif%20passif%20unicit%C3%A9%20patrimoine%20d%E2%80%99affectation%20premi%C3%A8re%20STMG%20droit"}],games:[{id:"p1-droit-t3-qcm",type:"qcm",title:"QCM — Les personnes",icon:"❓",questions:[{q:"La personnalité juridique est l’aptitude à…",choices:["être titulaire de droits et d’obligations","voter une loi","juger un litige","produire des biens"],answer:0,explain:"Elle fait de l’être un sujet de droit."},{q:"Une association déclarée est une personne…",choices:["morale","physique","publique par nature","sans patrimoine"],answer:0,explain:"Elle a un patrimoine propre, distinct de celui de ses membres."},{q:"Un majeur placé sous tutelle est…",choices:["représenté par son tuteur","totalement libre de tout acte","privé de personnalité juridique","un mineur"],answer:0,explain:"La tutelle représente le majeur ; la curatelle, elle, l’assiste."},{q:"Vendre un bien important est un acte…",choices:["de disposition","d’administration","de jouissance","de procédure"],answer:0,explain:"Les actes de disposition engagent le patrimoine ; les actes d’administration sont la gestion courante."},{q:"Depuis 2015, l’animal est reconnu comme…",choices:["un être vivant doué de sensibilité","une personne morale","une personne physique","un majeur protégé"],answer:0,explain:"Il reste néanmoins soumis pour l’essentiel au régime des biens."},{q:"Le principe selon lequel chaque personne n’a qu’un seul patrimoine est…",choices:["l’unicité","l’universalité","l’indivisibilité","l’incessibilité"],answer:0,explain:"Unicité = un seul patrimoine par personne (sauf patrimoine d’affectation)."},{q:"Le patrimoine comprend…",choices:["les droits et obligations évaluables en argent (actif et passif)","seulement les revenus","les opinions","la nationalité"],answer:0,explain:"Actif (biens) + passif (dettes), évaluables en argent."}]},{id:"p1-droit-t3-tri",type:"tri",title:"Tri — Patrimonial ou extrapatrimonial ?",icon:"🗂️",instruction:"Classe chaque droit.",categories:[{id:"pat",label:"Patrimonial"},{id:"ext",label:"Extrapatrimonial"}],items:[{text:"Le droit de propriété",cat:"pat"},{text:"Le droit à la vie privée",cat:"ext"},{text:"Une créance (somme due)",cat:"pat"},{text:"Le droit à l’image",cat:"ext"},{text:"Le droit au nom",cat:"ext"}]},{id:"p1-droit-t3-flash",type:"flashcard",title:"Flashcards — Les personnes",icon:"🃏",cards:[{front:"Personnalité juridique",back:"Aptitude à être titulaire de droits et d’obligations."},{front:"Personne morale",back:"Groupement au patrimoine propre distinct de ses membres."},{front:"Capacité de jouissance / d’exercice",back:"Avoir des droits / pouvoir les exercer soi-même."},{front:"Majeurs protégés",back:"Sauvegarde de justice, curatelle (assistance), tutelle (représentation)."},{front:"Patrimoine (principes)",back:"Unicité, universalité, indivisibilité, incessibilité (+ patrimoine d’affectation)."}]}]},{id:"p1-droit-t4",name:"Thème 4 — Quels sont les droits reconnus aux personnes ?",short:"Les droits des personnes",keywords:"droit de propriété usus fructus abusus caractères absolu exclusif perpétuel bien corporel incorporel trouble anormal du voisinage propriété intellectuelle industrielle marque brevet monopole d’exploitation action en contrefaçon droit d’auteur droit moral patrimonial droits de la personnalité vie privée image dignité protection des données RGPD CNIL inaliénable insaisissable imprescriptible",intro:"Les personnes disposent de **droits**. On étudie ici le **droit de propriété** (y compris la **propriété intellectuelle**) et les **droits de la personnalité**, essentiels à l’ère numérique (**données personnelles**).",cours:[{h:"Le droit de propriété : usus, fructus, abusus",blocks:[{t:"p",c:"Le droit de propriété est le droit le plus complet sur un **bien** (qui peut être **corporel** — une maison, une voiture — ou **incorporel** — une créance, une marque). Il comporte **trois attributs** :"},{t:"list",c:["**Usus** : le droit d’**utiliser** le bien.","**Fructus** : le droit d’en **percevoir les revenus** (ex. un loyer).","**Abusus** : le droit d’en **disposer** (vendre, détruire)."]},{t:"p",c:"On lui reconnaît trois **caractères** : **absolu** (le plus large possible), **exclusif** (le propriétaire est seul à en jouir) et **perpétuel** (il dure tant que le bien existe)."},{t:"warning",c:"Ces caractères connaissent des **limites** : respect de l’**intérêt général** (expropriation, urbanisme) et du voisinage. Ainsi, un **trouble anormal du voisinage** (bruit, nuisances excessives) engage la responsabilité de son auteur."}]},{h:"La propriété intellectuelle : marque, brevet, droit d’auteur",blocks:[{t:"p",c:"Les **créations de l’esprit** sont protégées. On distingue deux ensembles :"},{t:"table",head:["Propriété industrielle","Droit d’auteur"],rows:[["Protège les créations utiles à l’activité économique","Protège les œuvres de l’esprit (livre, musique, logiciel)"],["Marque (signe distinctif), brevet (invention)","Naît sans formalité, dès la création"],["Confère un monopole d’exploitation","Droit moral (perpétuel) + droits patrimoniaux (limités dans le temps)"]]},{t:"p",c:"La **marque** et le **brevet** confèrent à leur titulaire un **monopole d’exploitation**. Toute atteinte (copie, reproduction sans autorisation) constitue une **contrefaçon**, sanctionnée par une **action en contrefaçon**. Le **droit d’auteur** comprend un **droit moral** (respect du nom et de l’œuvre, inaliénable et perpétuel) et des **droits patrimoniaux** (exploiter l’œuvre et en tirer des revenus)."},{t:"example",h:"Le faux sac de marque",c:`Une boutique vend des sacs imitant le **logo** et le **nom** d’une grande marque. 
→ La marque est protégée par un **monopole d’exploitation** : reproduire son signe distinctif sans autorisation est une **contrefaçon**. Le titulaire peut engager une **action en contrefaçon** pour faire cesser la vente et obtenir des dommages et intérêts.`}]},{h:"Les droits de la personnalité et la protection des données",blocks:[{t:"p",c:"Les **droits de la personnalité** protègent la personne elle-même : droit au respect de la **vie privée**, droit à l’**image**, droit à la **dignité** et au **nom**. Ce sont des droits **extrapatrimoniaux**, aux caractères particuliers : **inaliénables** (on ne peut les vendre), **insaisissables** et **imprescriptibles**."},{t:"p",c:"À l’ère numérique, la **protection des données personnelles** est renforcée. Le **RGPD** (règlement européen) encadre la collecte et l’usage des données ; en France, la **CNIL** veille à leur respect et peut sanctionner les manquements."},{t:"example",h:"La photo publiée sans accord",c:`Un ami publie sur un réseau social une photo de Sarah, prise en soirée, sans lui demander. 
→ Le **droit à l’image** (droit de la personnalité, **inaliénable**) suppose l’**accord** de la personne. Sarah peut exiger le **retrait** de la photo et, en cas de préjudice, une réparation. Si le site conserve ses données, le **RGPD** lui donne aussi un droit d’**effacement**, dont la **CNIL** garantit le respect.`}]}],essentiel:["Droit de propriété = **usus** + **fructus** + **abusus** ; caractères **absolu, exclusif, perpétuel** (avec des **limites** : trouble anormal du voisinage, intérêt général).","Biens **corporels** vs **incorporels**.","Propriété intellectuelle : **marque / brevet** (propriété industrielle, monopole d’exploitation, **action en contrefaçon**) et **droit d’auteur** (droit **moral** + droits **patrimoniaux**).","**Droits de la personnalité** (vie privée, image, dignité) = extrapatrimoniaux, **inaliénables, insaisissables, imprescriptibles** ; données protégées par le **RGPD** et la **CNIL**."],resources:[{kind:"video",label:"Le droit de propriété (usus, fructus, abusus)",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=droit%20de%20propri%C3%A9t%C3%A9%20usus%20fructus%20abusus%20caract%C3%A8res%20absolu%20exclusif%20perp%C3%A9tuel%20premi%C3%A8re%20STMG"},{kind:"video",label:"Propriété intellectuelle, RGPD et données personnelles",note:"Vidéos — recherche YouTube",url:"https://www.youtube.com/results?search_query=propri%C3%A9t%C3%A9%20intellectuelle%20marque%20brevet%20contrefa%C3%A7on%20RGPD%20CNIL%20premi%C3%A8re%20STMG%20droit"}],games:[{id:"p1-droit-t4-qcm",type:"qcm",title:"QCM — Les droits des personnes",icon:"❓",questions:[{q:"Le droit de percevoir les revenus d’un bien (ex. un loyer) est…",choices:["le fructus","l’usus","l’abusus","l’usufruit du voisin"],answer:0,explain:"Usus = utiliser ; fructus = revenus ; abusus = disposer."},{q:"Vendre ou détruire un bien correspond à…",choices:["l’abusus","l’usus","le fructus","la médiation"],answer:0,explain:"L’abusus est le droit de disposer du bien."},{q:"Les caractères du droit de propriété sont…",choices:["absolu, exclusif, perpétuel","général, impersonnel, obligatoire","certain, direct, personnel","oral, écrit, tacite"],answer:0,explain:"Absolu (le plus large), exclusif (seul à en jouir), perpétuel (dure tant que le bien existe)."},{q:"Une marque protège…",choices:["un signe distinctif, avec un monopole d’exploitation","une invention technique uniquement","une œuvre littéraire","un salaire"],answer:0,explain:"La marque (propriété industrielle) donne un monopole d’exploitation ; le brevet protège l’invention."},{q:"Reproduire une œuvre sans autorisation constitue…",choices:["une contrefaçon","un acte authentique","un trouble du voisinage","une preuve parfaite"],answer:0,explain:"La contrefaçon est sanctionnée par une action en contrefaçon."},{q:"Le droit d’auteur comprend…",choices:["un droit moral et des droits patrimoniaux","seulement un droit à réparation","un monopole d’État","une preuve imparfaite"],answer:0,explain:"Droit moral (respect de l’œuvre, perpétuel) + droits patrimoniaux (exploiter, tirer des revenus)."},{q:"En France, l’organisme qui veille à la protection des données personnelles est…",choices:["la CNIL","la Cour de cassation","l’INSEE","l’Autorité de la concurrence"],answer:0,explain:"La CNIL applique le RGPD et peut sanctionner les manquements."}]},{id:"p1-droit-t4-assoc",type:"association",title:"Association — Notion ↔ sens",icon:"🔗",pairs:[{left:"Usus",right:"Utiliser le bien"},{left:"Fructus",right:"Percevoir les revenus (loyer)"},{left:"Abusus",right:"Disposer (vendre, détruire)"},{left:"Brevet",right:"Protège une invention (monopole d’exploitation)"},{left:"RGPD / CNIL",right:"Protection des données personnelles"}]},{id:"p1-droit-t4-vf",type:"vraifaux",title:"Vrai / Faux rapide",icon:"⚡",questions:[{statement:"Le droit de propriété autorise à causer un trouble anormal du voisinage.",answer:!1,explain:"Faux : c’est une limite au droit de propriété."},{statement:"La marque et le brevet confèrent un monopole d’exploitation.",answer:!0,explain:"Vrai : leur titulaire est seul à pouvoir les exploiter."},{statement:"Le droit à la vie privée est un droit de la personnalité, inaliénable.",answer:!0,explain:"Vrai : extrapatrimonial, inaliénable, insaisissable, imprescriptible."},{statement:"Une donnée personnelle peut être collectée et utilisée sans aucune règle.",answer:!1,explain:"Faux : le RGPD encadre la collecte et l’usage ; la CNIL veille."}]},{id:"p1-droit-t4-flash",type:"flashcard",title:"Flashcards — Les droits",icon:"🃏",cards:[{front:"Usus / fructus / abusus",back:"Utiliser / percevoir les revenus / disposer."},{front:"Caractères de la propriété",back:"Absolu, exclusif, perpétuel (avec des limites)."},{front:"Propriété industrielle",back:"Marque et brevet : monopole d’exploitation, protégé par l’action en contrefaçon."},{front:"Droit d’auteur",back:"Droit moral (perpétuel) + droits patrimoniaux (exploitation)."},{front:"Droits de la personnalité",back:"Vie privée, image, dignité : inaliénables, insaisissables, imprescriptibles."},{front:"RGPD / CNIL",back:"Cadre européen des données / autorité française de contrôle."}]}]}],p={id:e,name:i,short:t,icon:r,color:n,niveau:s,tagline:a,chapters:o},q=Object.freeze(Object.defineProperty({__proto__:null,chapters:o,color:n,default:p,icon:r,id:e,name:i,niveau:s,short:t,tagline:a},Symbol.toStringTag,{value:"Module"})),m={"p1-droit-t1":["Le **droit** organise la vie en société par des règles **obligatoires et sanctionnées** : ne le confonds pas avec la morale.","Distingue **droit objectif** (l’ensemble des règles) et **droits subjectifs** (les prérogatives d’une personne)."]},h=Object.freeze(Object.defineProperty({__proto__:null,default:m},Symbol.toStringTag,{value:"Module"}));export{b as a,f as b,g as d,v as e,q as m,h as p};
